#include "scene.hpp"
#include "title.hpp"
#include "presentation.hpp"
#include <iostream>
using namespace rhine;
static void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
int main(){try{
    json results=json::object();
    // A detail switch must keep its camera; rapid requests replace the target
    // during text exit and Esc must invalidate that request before commit.
    bool archiveReady=true,detailReady=true,detailMode=false;int cameraEntries=0,cameraReturns=0,selected=0,detailSwitches=0;std::function<void()> hideBrowse,hideDetail;
    PresentationPorts ports;ports.ready=[&]{return detailReady;};ports.archiveReady=[&]{return archiveReady;};ports.enter=[&]{++cameraEntries;};ports.back=[&]{++cameraReturns;};ports.prepare=[]{};ports.mode=[&](bool value){detailMode=value;};ports.select=[&](auto request){selected=request.index;};ports.switchDetail=[&](auto request){selected=request.index;++detailSwitches;};ports.showMenu=[]{};ports.showBrowse=[]{};ports.hideMenu=[&](auto completion){hideDetail=completion;};ports.hideBrowse=[&](auto completion){hideBrowse=completion;};
    Presentation presentation(ports);presentation.open();require(presentation.phase=="opening"&&cameraEntries==1&&detailMode,"Opening camera did not start");presentation.update();require(presentation.phase=="opening","Text appeared before browse exit");hideBrowse();presentation.update();require(presentation.phase=="detail","Opening did not complete");
    presentation.select({1},true);presentation.select({2},true);require(selected==0&&detailSwitches==0,"Selection committed before text exit");hideDetail();require(selected==2&&detailSwitches==1&&cameraEntries==1&&cameraReturns==0,"Detail selection changed camera composition");presentation.update();require(presentation.phase=="detail","Detail switch did not settle");
    presentation.select({3},true);presentation.back();hideDetail();presentation.update();require(selected==2&&cameraReturns==1&&!detailMode&&presentation.phase=="archive","Esc failed to cancel pending selection");
    presentation.open();hideBrowse();presentation.update();presentation.select({4,0,false,true},true);hideDetail();require(cameraReturns==2&&selected==2,"Cross-album location skipped archive");presentation.update();require(selected==4&&presentation.phase=="selecting","Location did not move on archive");presentation.update();require(cameraEntries==3&&presentation.phase=="opening","Location did not reopen");results["presentationOrdering"]=true;
    SurfaceMotion surface;surface.move(true,0,false);surface.sample(.13);const double value=surface.opacity,offset=surface.offset;surface.move(false,.13,false);require(std::abs(surface.opacity-value)<1e-8&&std::abs(surface.offset-offset)<1e-8,"Surface jumped on interruption");surface.sample(.37);require(surface.opacity<1e-7,"Surface exit did not finish in 240ms");results["surfaceInterruption"]=true;
    // Compare a title sample to the upstream 460ms critical-damping equation;
    // a new line must start as an empty face and roll into the existing title.
    TitleTrack roll;roll.set(0);roll.move(56,0);auto sample=roll.sample(.23);double reference=56+(-56-560*.5)*std::exp(-5);require(std::abs(sample.value-reference)<1e-8,"Title trajectory differs from original");roll.move(112,.23);require(std::abs(roll.sample(.23).value-sample.value)<1e-8&&std::abs(roll.sample(.23).velocity-sample.velocity)<1e-8,"Title velocity was lost on interruption");require(roll.sample(.7).value==112,"Title did not finish in 460ms");
    NativeTitle title;TitleGlyph glyph{"main:0:0",{L"A",40,56,24,700},0,0};title.apply({glyph},56,0,false);TitleGlyph second{"main:1:0",{L"g",40,56,24,700},0,56};title.apply({glyph,second},112,1,true);const auto& newLine=title.slots.at("main:1:0");require(newLine.faces.size()==2&&newLine.faces.front().text.empty()&&newLine.roll.moving,"New title line appeared statically");results["title460msAndNewLines"]=true;
    json library={{"albums",json::array({{{"id","a"}},{{"id","b"}},{{"id","c"}}})},{"columnFiles",json::array({json::array({0,1,2})})}};
    Scene scene;scene.library(library);scene.skip();double now=0;SceneFrame frame;auto advance=[&](int count,bool reduced=false){for(int i=0;i<count;++i){now+=1./120;frame=scene.update(now,1./120,1920,1080,reduced);for(const auto& instance:frame.instances){const auto* matrix=&instance.world._11;for(int j=0;j<16;++j)require(std::isfinite(matrix[j]),"Nonfinite instance transform");}require(frame.instances.size()<=439,"Unbounded outgoing cases");}};
    advance(1,true);require(frame.instances.size()==433&&scene.canOpen(),"Original fixed pool or skip behavior changed");scene.open();advance(180);require(scene.ready()&&frame.detail==1,"Detail placement failed to settle");scene.rotate(.7);advance(150);const double rotation=frame.rotation,height=frame.selected.y;require(rotation>.5,"Card rotation did not respond");scene.back();advance(1);require(frame.detail>.99&&std::abs(frame.selected.y-height)<.0001,"Rotated case returned before alignment");advance(600);require(scene.canOpen()&&std::abs(frame.rotation)<.001,"Return failed to align and settle");
    for(int i=1;i<300;++i){scene.select(i%3,now,false,1,false);advance(1,true);require(scene.selected()==i%3,"Cyclic selection lost album identity");}
    scene.library({{"albums",json::array({{{"id","c"}},{{"id","a"}},{{"id","b"}}})},{"columnFiles",json::array({json::array({0,1,2})})}});require(scene.selected()==0,"Refresh did not preserve selected album ID");advance(1,true);results["sceneContinuityPoolAndIdentity"]=true;
    Scene lateLibrary;lateLibrary.library({{"albums",json::array()},{"columnFiles",json::array()}});lateLibrary.skip();lateLibrary.update(0,.016,1280,720,true);require(lateLibrary.selected()==-1,"Empty library selection was not empty");lateLibrary.library(library);require(lateLibrary.selected()==0,"Late optical-drive/library discovery did not select its first album");lateLibrary.update(.016,.016,1280,720,true);lateLibrary.open();for(int i=0;i<180;++i)lateLibrary.update(.032+i/120.,1./120,1280,720,false);require(lateLibrary.detail()&&lateLibrary.ready(),"Late discovered album could not enter detail");results["lateLibraryDiscovery"]=true;
    Scene discScene;discScene.library({{"albums",json::array({{{"id","cd-test"},{"cd",{{"drive","F:"}}}},{{"id","regular"}}})},{"columnFiles",json::array({json::array({0,1})})}});discScene.skip();discScene.transport("cd-test",true);discScene.update(0,.025,1280,720,false);double spun=discScene.discStatus().at("angles").at("cd-test");require(spun>.5,"Playing disc did not rotate");discScene.transport("cd-test",false);for(int i=0;i<120;++i)discScene.update(i*.016,.016,1280,720,false);require(discScene.discStatus().at("angles").at("cd-test")==spun,"Paused disc drifted");discScene.transport("regular",true);discScene.update(2,.05,1280,720,false);require(discScene.discStatus().at("angles").at("cd-test")==spun,"Different album rotated the CD");discScene.transport("cd-test",true);discScene.update(3,.05,1280,720,true);require(discScene.discStatus().at("angles").at("cd-test")==spun,"Reduced motion rotated the disc");results["discPlaybackMotion"]=true;
    results["ok"]=true;std::cout<<results.dump(2)<<"\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<"\n";return 1;}}
